/* MODULE tp09 · Bước 4 Tạo thông điệp · Kể chuyện thương hiệu không sến
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tp09', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tp09-01', skill:'creative', read:'6 phút', t:'Kịch bản 60 giây của bạn có phải là một câu chuyện không?',
  situation:'Một thương hiệu bột giặt ở Bình Dương nhận kịch bản TVC 60 giây từ agency: mở bằng cảnh gia đình cười, rồi cận cảnh bọt giặt, rồi chữ "Sạch thơm, cả nhà vui", kết bằng logo. Sếp đọc xong hỏi: "Chuyện ở đâu?" Agency khẳng định đây là "brand storytelling". Test nhanh với 40 người xem, chỉ 6 người kể lại được clip nói về điều gì.',
  concept:{ name:'Nhân vật – trở ngại – thay đổi',
    body:'Một chuỗi hình đẹp chưa phải câu chuyện. Câu chuyện cần ba thứ: một <b>nhân vật</b> người xem nhận ra, một <b>trở ngại</b> nhân vật thật sự muốn vượt qua, và một <b>sự thay đổi</b> — cuối chuyện có gì đó khác đầu chuyện. Thiếu trở ngại thì không có lý do để xem tiếp; thiếu thay đổi thì không có gì để nhớ. Sản phẩm, nếu xuất hiện, nên là thứ giúp tạo ra sự thay đổi, không phải là nhân vật đứng giữa khung hình.' },
  example:'Viết lại: một cậu bé lớp 3 được chọn làm cầm cờ ngày khai giảng, nhưng chiếc áo trắng duy nhất dính vết nước tương từ tối hôm trước (nhân vật + trở ngại). Mẹ giặt lúc 10 giờ đêm, sáng ra áo trắng, cậu đứng thẳng lưng dưới sân trường (thay đổi). Test lại với 40 người: 29 người kể lại được đúng mạch chuyện, so với 6 người ở bản cũ.',
  takeaway:'Không có trở ngại và thay đổi thì chỉ là một chuỗi cảnh đẹp, chưa phải câu chuyện.',
  apply:'Lấy một quảng cáo bạn vừa xem, nói trong 60 giây: nhân vật là ai, trở ngại là gì, cuối chuyện cái gì đã thay đổi.',
  mistakes:['Gọi một chuỗi cảnh sản phẩm đẹp là "storytelling".','Để trở ngại quá nhỏ hoặc giải quyết ngay giây đầu, người xem không kịp quan tâm.'],
  q:[
  { type:'mcq', stem:'Kịch bản: cảnh gia đình cười → cận cảnh bọt giặt → slogan → logo. Vì sao chỉ 6/40 người kể lại được?',
    options:[{k:'a',t:'Clip thiếu một người nổi tiếng đủ sức giữ chân người xem'},{k:'b',t:'Không có trở ngại và thay đổi, nên không có mạch nào để nhớ'},
             {k:'c',t:'Clip 60 giây quá dài với người xem thời nay, nên cắt còn 15 giây sẽ nhớ hơn'},{k:'d',t:'Slogan chưa đủ vần để đọng lại trong đầu người xem'}],
    answer:'b', why:{a:'Người nổi tiếng tăng chú ý nhưng không tự tạo ra mạch chuyện để kể lại.',
      b:'Đúng. Não người nhớ chuỗi "muốn – bị cản – vượt qua"; thiếu nó thì chỉ còn các cảnh rời rạc.',
      c:'Cắt ngắn một chuỗi cảnh rời rạc vẫn là chuỗi cảnh rời rạc; độ dài không phải gốc vấn đề.',
      d:'Slogan có vần giúp nhớ câu chữ, nhưng người xem vẫn không biết clip kể chuyện gì.'} },
  { type:'mcq', stem:'Bạn chỉ được sửa một điểm trong kịch bản bột giặt trước khi quay. Bạn sửa gì?',
    options:[{k:'a',t:'Thêm cảnh so sánh áo giặt bằng bột thường và bột của hãng ngay giữa clip cho thuyết phục'},{k:'b',t:'Đổi nhạc nền sang một bài đang thịnh hành để tăng cảm xúc'},
             {k:'c',t:'Tăng thời lượng cận cảnh bọt giặt để khoe công nghệ mới'},{k:'d',t:'Cho một nhân vật cụ thể gặp một trở ngại thật mà sản phẩm giúp vượt qua'}],
    answer:'d', why:{a:'Cảnh so sánh là chứng minh công năng, có ích nhưng vẫn không tạo ra câu chuyện.',
      b:'Nhạc tạo không khí, không tạo ra nhân vật hay trở ngại.',
      c:'Thêm thời lượng cho sản phẩm càng biến clip thành catalogue.',
      d:'Đúng. Có nhân vật và trở ngại thì mọi cảnh còn lại mới có lý do tồn tại.'} },
  { type:'mcq', stem:'Trong ba thành phần, thành phần nào khi thiếu sẽ khiến người xem không có lý do để xem tiếp?',
    options:[{k:'a',t:'Trở ngại'},{k:'b',t:'Logo xuất hiện sớm ngay từ giây đầu'},
             {k:'c',t:'Sự thay đổi ở cuối chuyện'},{k:'d',t:'Nhân vật có ngoại hình đẹp, dễ gây thiện cảm'}],
    answer:'a', why:{a:'Đúng. Trở ngại tạo câu hỏi "rồi sao?" — thứ kéo người xem đi tiếp.',
      b:'Logo sớm giúp nhận diện thương hiệu, không liên quan đến lý do xem tiếp.',
      c:'Thiếu thay đổi thì không có gì để nhớ, nhưng người xem đã xem hết rồi mới thất vọng.',
      d:'Ngoại hình đẹp giữ mắt vài giây, không giữ được sự tò mò.'} },
  { type:'mcq', stem:'Một clip cà phê: anh nhân viên văn phòng mệt mỏi → uống cà phê → vẫn mệt mỏi nhưng mỉm cười. Vấn đề nằm ở đâu?',
    options:[{k:'a',t:'Nhân vật văn phòng quá quen thuộc, người xem đã chán'},{k:'b',t:'Trở ngại mệt mỏi quá nhỏ để thành chuyện'},
             {k:'c',t:'Sự thay đổi mờ nhạt: cuối chuyện gần như giống đầu chuyện'},{k:'d',t:'Clip thiếu cảnh pha cà phê cận cảnh để khơi gợi vị giác'}],
    answer:'c', why:{a:'Nhân vật quen thuộc không sao, người xem nhận ra mình là điều tốt.',
      b:'Mệt mỏi có thể thành chuyện nếu có hệ quả cụ thể, ví dụ sắp phải thuyết trình.',
      c:'Đúng. Không thấy điều gì khác đi, người xem không có gì để kể lại.',
      d:'Cảnh cận sản phẩm không sửa được mạch chuyện đứng yên.'} },
  { type:'mcq', stem:'Tình huống mới: một ngân hàng muốn "kể chuyện" về ứng dụng chuyển tiền nhanh. Nhân vật và trở ngại nào tạo được chuyện rõ nhất?',
    options:[{k:'a',t:'Ứng dụng tự giới thiệu các tính năng bằng giọng đọc hoạt hình vui nhộn, dễ thương, dễ nhớ'},{k:'b',t:'Một sinh viên phải gửi tiền học phí trước 17 giờ, đang kẹt ở quê không có phòng giao dịch'},
             {k:'c',t:'Một người trẻ thành đạt dùng ứng dụng trong văn phòng sang trọng'},{k:'d',t:'Ban lãnh đạo ngân hàng kể về tầm nhìn chuyển đổi số'}],
    answer:'b', why:{a:'Sản phẩm làm nhân vật thì không có ai để người xem đứng về phía.',
      b:'Đúng. Có người cụ thể, có hạn chót, có trở ngại thật — ứng dụng xuất hiện như lối thoát.',
      c:'Không có trở ngại nào; người thành đạt trong văn phòng đẹp chỉ là hình ảnh.',
      d:'Tầm nhìn của ngân hàng không phải điều khách đang cần vượt qua.'} },
  { type:'calc', stem:'Test với 40 người: bản cũ 6 người kể lại được mạch chuyện, bản viết lại 29 người. Tỉ lệ kể lại tăng thêm bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:57.5, tol:0.1, wrong:[[383.3,'NHAM_DIEM_PHAN_TRAM'],[23,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Bản cũ: 6 ÷ 40 = 15%.','Bản viết lại: 29 ÷ 40 = 72,5%.','Tăng: 72,5% − 15% = <b>57,5 điểm phần trăm</b>.'] },
  { type:'mcq', stem:'Câu nào mô tả đúng vai trò của sản phẩm trong khung nhân vật – trở ngại – thay đổi?',
    options:[{k:'a',t:'Sản phẩm là thứ giúp tạo ra sự thay đổi cho nhân vật'},{k:'b',t:'Sản phẩm phải là nhân vật chính để khách nhớ thương hiệu'},
             {k:'c',t:'Sản phẩm nên xuất hiện liên tục từ đầu đến cuối clip để chắc chắn được nhớ'},{k:'d',t:'Sản phẩm là trở ngại mà nhân vật phải vượt qua'}],
    answer:'a', why:{a:'Đúng. Sản phẩm gắn vào điểm ngoặt của chuyện thì được nhớ cùng chuyện.',
      b:'Người xem không đồng cảm với một gói bột giặt; họ đồng cảm với con người.',
      c:'Xuất hiện liên tục biến chuyện thành quảng cáo trưng bày, người xem bỏ qua.',
      d:'Sản phẩm là trở ngại thì thương hiệu đang tự nói xấu mình.'} },
  ]},

/* ------------------------------------------------------------------ 02 */
{ id:'B:tp09-02', skill:'creative', read:'6 phút', t:'Ai là nhân vật chính: khách hàng hay thương hiệu?',
  situation:'Một chuỗi trung tâm tiếng Anh ở Hà Nội làm series video "Hành trình 10 năm của chúng tôi": phòng học mới, giáo viên bản ngữ, giải thưởng. Ba tập đầu đạt trung bình 1.200 lượt xem mỗi tập. Một tập thử nghiệm kể về chị bán xôi 42 tuổi học giao tiếp để bán cho khách du lịch phố cổ đạt 18.000 lượt xem, và 140 tin nhắn hỏi khoá học.',
  concept:{ name:'Khách là người hùng, thương hiệu là người dẫn đường',
    body:'Trong phần lớn câu chuyện hay, người xem đứng về phía <b>người hùng</b> — người đang gặp trở ngại. Nếu thương hiệu tự nhận vai người hùng, khách chỉ còn vai khán giả vỗ tay. Vai hợp hơn cho thương hiệu là <b>người dẫn đường</b>: hiểu nỗi khó của người hùng, đưa ra một kế hoạch hoặc công cụ, rồi lùi lại để người hùng tự chiến thắng. Người xem thấy mình trong người hùng, và thấy thương hiệu là người có thể giúp mình.' },
  example:'Tập "chị bán xôi": chị là người hùng (muốn nói chuyện với khách Tây, sợ nói sai bị cười). Trung tâm là người dẫn đường: lớp buổi tối 45 phút, 20 câu dùng ngay ở quầy xôi. Cuối clip, chị tự chào một khách Úc và bán được hai hộp. Chuyển đổi: 140 tin nhắn trên 18.000 lượt xem, khoảng 0,78%, trong khi ba tập "về chúng tôi" gần như không có tin nhắn.',
  takeaway:'Để khách làm người hùng; thương hiệu là người đưa tấm bản đồ, không phải người nhận huy chương.',
  apply:'Viết lại câu mở đầu trang "Về chúng tôi" của một thương hiệu bạn biết sao cho chủ ngữ là khách hàng, không phải công ty.',
  mistakes:['Kể thành tích công ty rồi gọi đó là câu chuyện thương hiệu.','Để thương hiệu "giải cứu" quá nhiều, người hùng thành bị động.'],
  q:[
  { type:'mcq', stem:'Vì sao tập "chị bán xôi" có lượt xem gấp 15 lần các tập "hành trình 10 năm"?',
    options:[{k:'a',t:'Người xem thấy mình trong một người hùng đang gặp trở ngại thật'},{k:'b',t:'Chủ đề ẩm thực đường phố luôn có lượt xem cao hơn chủ đề giáo dục trên mạng xã hội'},
             {k:'c',t:'Tập đó được chạy quảng cáo nhiều tiền hơn'},{k:'d',t:'Người xem thích thấy người lớn tuổi đi học'}],
    answer:'a', why:{a:'Đúng. Người xem đứng về phía người có trở ngại; thành tích của công ty không cho họ ai để đứng cùng.',
      b:'Chủ đề có thể góp phần, nhưng lượng tin nhắn hỏi khoá học cho thấy người xem gắn với nhu cầu học, không chỉ với xôi.',
      c:'Tình huống không nói có ngân sách khác nhau; và tiền quảng cáo không giải thích được 140 tin nhắn.',
      d:'Tuổi là chi tiết, không phải lý do; điều hút người xem là trở ngại và sự thay đổi.'} },
  { type:'mcq', stem:'Series tiếp theo còn ngân sách 6 tập. Bạn làm gì?',
    options:[{k:'a',t:'Giữ 3 tập "về chúng tôi" và thêm 3 tập học viên cho cân bằng'},{k:'b',t:'Làm 6 tập về giáo viên bản ngữ vì đó là điểm khác biệt lớn nhất của trung tâm'},
             {k:'c',t:'Làm 6 tập, mỗi tập một học viên có trở ngại cụ thể, trung tâm chỉ là người dẫn đường'},{k:'d',t:'Làm lại tập chị bán xôi với diễn viên chuyên nghiệp'}],
    answer:'c', why:{a:'Chia đôi để "cân bằng" là giữ lại phần đã chứng minh không hiệu quả.',
      b:'Giáo viên là công cụ của người dẫn đường; biến họ thành người hùng vẫn lặp lại lỗi cũ.',
      c:'Đúng. Nhân rộng cấu trúc đã hiệu quả, mỗi tập một người hùng khác để chạm nhiều nhóm khách.',
      d:'Diễn viên thay người thật làm mất độ tin — thứ tạo nên thành công của tập đó.'} },
  { type:'calc', stem:'Tập "chị bán xôi" có 18.000 lượt xem và 140 tin nhắn hỏi khoá học. Tỉ lệ tin nhắn trên lượt xem là bao nhiêu phần trăm? (làm tròn 2 chữ số thập phân)',
    unit:'%', ans:0.78, tol:0.01, wrong:[[128.57,'SAI_MAU_SO'],[7.78,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = tin nhắn ÷ lượt xem.','140 ÷ 18.000 ≈ 0,00778 = <b>0,78%</b>.'] },
  { type:'mcq', stem:'Trong vai người dẫn đường, thương hiệu nên làm điều nào?',
    options:[{k:'a',t:'Xuất hiện ở cuối, nhận lời cảm ơn và khoe giải thưởng của mình'},{k:'b',t:'Thay người hùng giải quyết mọi việc cho nhanh gọn'},
             {k:'c',t:'Kể về khó khăn của chính công ty khi mới thành lập để người xem thương cảm'},{k:'d',t:'Hiểu nỗi khó, đưa một kế hoạch rõ, để người hùng tự vượt qua'}],
    answer:'d', why:{a:'Nhận huy chương là giành lại vai người hùng.',
      b:'Người hùng bị động thì người xem không còn thấy mình trong đó.',
      c:'Kể khó khăn của công ty là đổi vai: công ty lại thành người hùng.',
      d:'Đúng. Đồng cảm + kế hoạch là hai thứ khiến người xem tin người dẫn đường.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng sơn viết "Chúng tôi tự hào 20 năm kiến tạo tổ ấm Việt". Sửa theo hướng khách là người hùng thế nào?',
    options:[{k:'a',t:'"20 năm, hơn 1 triệu ngôi nhà đã chọn chúng tôi"'},{k:'b',t:'"Căn phòng con gái bạn tự chọn màu, sơn xong trong một cuối tuần"'},
             {k:'c',t:'"Chúng tôi là hãng sơn được yêu thích nhất suốt nhiều năm"'},{k:'d',t:'"Công nghệ sơn Đức, chuẩn chất lượng quốc tế"'}],
    answer:'b', why:{a:'Vẫn là thành tích của hãng, khách chỉ là con số.',
      b:'Đúng. Chủ ngữ là khách và con, có mục tiêu cụ thể; hãng sơn đứng sau như công cụ.',
      c:'Tự khen là giọng người hùng tự xưng, không có chỗ cho khách.',
      d:'Nói về công nghệ của hãng, không có nhân vật hay trở ngại nào.'} },
  { type:'mcq', stem:'Một clip để thương hiệu "giải cứu" mọi thứ: nhân vật chỉ ngồi chờ, nhân viên hãng làm hết. Rủi ro là gì?',
    options:[{k:'a',t:'Clip sẽ bị đánh giá là quá dài vì có nhiều cảnh nhân viên'},{k:'b',t:'Người xem nghi ngờ nhân viên đó là diễn viên thuê'},
             {k:'c',t:'Người hùng thành bị động, người xem mất chỗ để thấy mình trong câu chuyện'},{k:'d',t:'Thương hiệu bị cho là khoe khoang vì chiếm quá nhiều thời lượng'}],
    answer:'c', why:{a:'Độ dài không phải vấn đề chính.',
      b:'Có thể, nhưng đó là chuyện chi tiết sản xuất, không phải lỗi cấu trúc.',
      c:'Đúng. Khách muốn thấy mình làm được với sự giúp đỡ, không phải được làm hộ hoàn toàn.',
      d:'Có phần đúng, nhưng lỗi gốc là người hùng mất vai chủ động.'} },
  { type:'mcq', stem:'Khi nào kể về chính thương hiệu (thay vì khách) vẫn hợp lý?',
    options:[{k:'a',t:'Khi thương hiệu vừa đạt giải thưởng lớn cần được lan toả thật nhanh'},{k:'b',t:'Khi muốn tăng lượt theo dõi trang trong thời gian ngắn'},
             {k:'c',t:'Khi đối thủ đang làm video về khách hàng của họ'},{k:'d',t:'Khi câu chuyện đó trả lời một nỗi lo của khách, như "vì sao tin được"'}],
    answer:'d', why:{a:'Giải thưởng là tin nội bộ; khách chỉ quan tâm nếu nó giải một nỗi lo của họ.',
      b:'Lượt theo dõi không tự sinh ra từ việc nói về mình.',
      c:'Né đối thủ không phải lý do; cấu trúc người hùng vẫn hiệu quả.',
      d:'Đúng. Chuyện về thương hiệu có ích khi nó phục vụ người hùng, ví dụ giải toả nỗi sợ bị lừa.'} },
  ]},

/* ------------------------------------------------------------------ 03 */
{ id:'B:tp09-03', skill:'brand', read:'7 phút', t:'Chuyện người sáng lập: khi nào nên kể, khi nào nên cất?',
  situation:'Một thương hiệu nước mắm ở Phú Quốc do một kỹ sư 34 tuổi bỏ việc ở TP.HCM về làm lại nghề của ông nội. Một thương hiệu khác bán ốp lưng điện thoại do hai bạn trẻ lập ra "vì đam mê công nghệ". Cả hai đều định làm clip "Câu chuyện người sáng lập" với ngân sách như nhau, 80 triệu đồng.',
  concept:{ name:'Chuyện người sáng lập phải trả lời câu hỏi của khách',
    body:'Chuyện người sáng lập có ích khi nó là <b>bằng chứng</b> cho điều khách đang nghi ngờ. Với nước mắm, khách lo "có pha hoá chất không, có đúng truyền thống không" — chuyện người cháu về làm lại nghề ông nội trả lời thẳng nỗi lo đó. Với ốp lưng, khách lo "có bền, có vừa máy, giá có hời" — chuyện "đam mê công nghệ" không trả lời được gì. Kiểm tra bằng một câu: <b>chuyện này giúp khách tin điều gì mà trước đó họ chưa tin?</b> Không trả lời được thì cất đi.' },
  example:'Nước mắm: clip 90 giây, người sáng lập đứng cạnh thùng gỗ ông nội để lại, cho xem quy trình ủ 12 tháng, chỉ cá và muối. Khách xem xong có lý do tin "truyền thống thật". Ốp lưng: thay vì chuyện sáng lập, dùng 80 triệu để làm clip thả rơi ốp từ độ cao 1,5 mét 50 lần — trả lời đúng nỗi lo "có bền không".',
  takeaway:'Chuyện người sáng lập chỉ đáng kể khi nó là bằng chứng cho điều khách đang nghi ngờ.',
  apply:'Chọn một thương hiệu nhỏ bạn biết. Nói trong 60 giây: khách đang nghi ngờ điều gì, và chuyện người sáng lập có trả lời điều đó không.',
  mistakes:['Kể chuyện sáng lập vì "thương hiệu nào cũng có", không gắn với nỗi lo của khách.','Đẩy người sáng lập thành người hùng lấn át khách hàng.'],
  q:[
  { type:'mcq', stem:'Hai thương hiệu (nước mắm, ốp lưng) cùng muốn làm clip người sáng lập. Theo bạn, bên nào hưởng lợi nhiều hơn?',
    options:[{k:'a',t:'Như nhau vì chuyện người sáng lập luôn tạo được thiện cảm với khách'},{k:'b',t:'Ốp lưng, vì người trẻ thích chuyện khởi nghiệp'},
             {k:'c',t:'Nước mắm, vì chuyện đó trả lời nỗi lo về nguồn gốc và truyền thống'},{k:'d',t:'Không bên nào, vì khách không quan tâm ai lập ra công ty'}],
    answer:'c', why:{a:'Thiện cảm chung chung không chuyển thành lý do mua.',
      b:'Khởi nghiệp có thể hấp dẫn, nhưng không trả lời "ốp có bền không".',
      c:'Đúng. Ngành hàng mà nguồn gốc là nỗi lo thì chuyện người làm ra nó là bằng chứng.',
      d:'Quá tuyệt đối; khách quan tâm khi chuyện đó liên quan đến điều họ nghi ngờ.'} },
  { type:'mcq', stem:'Bạn là marketer của thương hiệu ốp lưng, có 80 triệu. Bạn chọn làm gì?',
    options:[{k:'a',t:'Clip người sáng lập kể về đam mê công nghệ và những đêm thức trắng khởi nghiệp'},{k:'b',t:'Clip thử độ bền thực tế, trả lời thẳng nỗi lo "có bền không"'},
             {k:'c',t:'Chia đôi: 40 triệu chuyện sáng lập, 40 triệu thử độ bền'},{k:'d',t:'Thuê KOL công nghệ đập hộp nhiều mẫu ốp một lượt'}],
    answer:'b', why:{a:'Đam mê của người sáng lập không giải toả nỗi lo nào của khách mua ốp.',
      b:'Đúng. Tiền nên đi vào bằng chứng cho điều khách đang nghi ngờ.',
      c:'Chia đôi vẫn tiêu một nửa vào phần không trả lời câu hỏi nào.',
      d:'Đập hộp giới thiệu mẫu mã, chưa chứng minh độ bền — nỗi lo chính.'} },
  { type:'mcq', stem:'Câu kiểm tra nào quyết định có nên kể chuyện người sáng lập?',
    options:[{k:'a',t:'Người sáng lập có ngoại hình và giọng nói lên hình tốt không?'},{k:'b',t:'Chuyện này có đủ cảm động để người xem chia sẻ không?'},
             {k:'c',t:'Đối thủ trong ngành đã có ai kể chuyện người sáng lập chưa, để mình đi trước?'},{k:'d',t:'Chuyện này giúp khách tin điều gì mà trước đó họ chưa tin?'}],
    answer:'d', why:{a:'Lên hình tốt là điều kiện sản xuất, không phải lý do chiến lược.',
      b:'Cảm động mà không gắn với nỗi lo của khách thì chia sẻ xong cũng quên.',
      c:'Đi trước đối thủ không có nghĩa là đúng nhu cầu khách.',
      d:'Đúng. Chuyện người sáng lập là bằng chứng; không chứng minh được gì thì không đáng tiền.'} },
  { type:'mcq', stem:'Tình huống mới: một phòng khám nha khoa tư nhân. Chi tiết nào trong chuyện bác sĩ sáng lập đáng đưa lên nhất?',
    options:[{k:'a',t:'Bác sĩ từng làm 8 năm ở khoa răng hàm mặt bệnh viện công, tự tay làm hơn 3.000 ca'},{k:'b',t:'Bác sĩ mơ ước mở phòng khám từ khi còn nhỏ, từng vượt qua nhiều khó khăn trong những năm đầu học y'},
             {k:'c',t:'Bác sĩ thích du lịch và chụp ảnh'},{k:'d',t:'Phòng khám có nội thất phong cách Bắc Âu'}],
    answer:'a', why:{a:'Đúng. Khách nha khoa lo tay nghề; chi tiết kinh nghiệm cụ thể trả lời nỗi lo đó.',
      b:'Ước mơ tạo thiện cảm nhưng không nói gì về tay nghề.',
      c:'Sở thích cá nhân không liên quan đến nỗi lo khi điều trị.',
      d:'Nội thất không phải chuyện người sáng lập và không trả lời nỗi lo chính.'} },
  { type:'mcq', stem:'Clip nước mắm để người sáng lập nói 80% thời lượng về mình, khách hàng không xuất hiện. Nên chỉnh thế nào?',
    options:[{k:'a',t:'Giữ nguyên, vì chuyện sáng lập thì người sáng lập phải là trung tâm'},{k:'b',t:'Cắt hẳn người sáng lập, thay bằng khách hàng kể'},
             {k:'c',t:'Giữ phần bằng chứng (thùng ủ, 12 tháng), thêm cảnh bữa cơm của người mua'},{k:'d',t:'Thêm nhạc cảm động và hình ảnh ông nội để tăng cảm xúc cho toàn bộ clip'}],
    answer:'c', why:{a:'Người sáng lập là bằng chứng, không cần chiếm hết vai; khách vẫn nên thấy mình trong đó.',
      b:'Cắt hẳn là bỏ đi bằng chứng quý nhất của thương hiệu này.',
      c:'Đúng. Người sáng lập đóng vai người dẫn đường đáng tin, người mua là người hưởng thay đổi.',
      d:'Thêm cảm xúc không sửa được việc câu chuyện chỉ xoay quanh người kể.'} },
  { type:'calc', stem:'Hãng ốp lưng chi 80 triệu đồng cho clip thử độ bền, clip đạt 400.000 lượt xem. Chi phí cho mỗi 1.000 lượt xem là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:200, tol:0.5, wrong:[[0.2,'SAI_TINH_TOAN'],[5,'SAI_MAU_SO']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Số nhóm 1.000 lượt xem: 400.000 ÷ 1.000 = 400.','Chi phí mỗi 1.000 lượt: 80.000.000 ÷ 400 = 200.000đ = <b>200 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Ngành hàng nào chuyện người sáng lập thường ít tác dụng nhất?',
    options:[{k:'a',t:'Thực phẩm thủ công, nơi khách lo về nguồn gốc'},{k:'b',t:'Mỹ phẩm handmade, nơi khách lo thành phần'},
             {k:'c',t:'Dịch vụ tư vấn, nơi khách mua bằng niềm tin vào người'},{k:'d',t:'Pin sạc dự phòng, nơi khách so dung lượng và giá'}],
    answer:'d', why:{a:'Nguồn gốc là nỗi lo chính, chuyện người làm ra là bằng chứng.',
      b:'Thành phần và sự chân thành của người làm có liên quan trực tiếp.',
      c:'Khách mua chính con người, chuyện người sáng lập rất đáng giá.',
      d:'Đúng. Khách so thông số; chuyện người sáng lập không trả lời câu hỏi nào của họ.'} },
  ]},

/* ------------------------------------------------------------------ 04 */
{ id:'B:tp09-04', skill:'creative', read:'7 phút', t:'Cảm xúc thật hay "lấy nước mắt"?',
  situation:'Một thương hiệu sữa làm clip Vu Lan: nhạc buồn, mẹ già ngồi một mình, con đi xa không về, chữ hiện lên "Đừng để quá muộn". Clip đạt 2 triệu lượt xem trong ba ngày nhưng bình luận chia hai: một nửa khen "khóc thật", một nửa chê "lại bán sữa bằng nước mắt". Khảo sát sau chiến dịch: chỉ 22% người xem nhớ đúng thương hiệu.',
  concept:{ name:'Cảm xúc sinh ra từ sự thật, không từ kỹ xảo',
    body:'Người xem cảm thấy bị "lấy nước mắt" khi cảm xúc được <b>ép</b> bằng nhạc, bằng cảnh bi thảm, bằng câu chữ đạo lý — mà không có một sự thật nhỏ nào họ nhận ra từ đời mình. Cảm xúc thật đến từ một <b>quan sát đúng</b>: một hành động nhỏ, một câu nói quen, một khoảnh khắc ai cũng từng trải. Dấu hiệu nhận biết: bỏ nhạc đi, cảnh đó còn chạm không? Nếu không, cảm xúc đang nằm ở nhạc chứ không nằm ở câu chuyện.' },
  example:'Viết lại: mẹ gọi video cho con, cứ hỏi "ăn cơm chưa" ba lần trong một cuộc gọi, rồi lén chỉnh camera để con không thấy tóc mẹ bạc thêm. Không nhạc buồn, không lời thoại đạo lý. Sữa xuất hiện khi con gửi về thùng sữa kèm mẩu giấy "Mẹ uống cho khoẻ, Tết con về". Người xem nhận ra mẹ mình trong câu hỏi lặp lại — đó là cảm xúc thật.',
  takeaway:'Bỏ nhạc đi mà cảnh vẫn chạm, đó là cảm xúc thật; không chạm nữa, đó là kỹ xảo.',
  apply:'Nghĩ về một người thân. Viết một hành động nhỏ rất riêng của họ mà ai cũng nhận ra — đó là nguyên liệu cho một cảnh chạm.',
  mistakes:['Dùng bi kịch lớn (bệnh tật, mất mát) để ép cảm xúc cho sản phẩm thường ngày.','Để lời thoại giảng đạo lý thay cho hành động.'],
  q:[
  { type:'mcq', stem:'Clip Vu Lan 2 triệu view nhưng chỉ 22% nhớ đúng thương hiệu. Theo bạn, nguyên nhân khả dĩ nhất?',
    options:[{k:'a',t:'Clip quá ngắn, không đủ thời gian để người xem kịp ghi nhớ tên thương hiệu'},{k:'b',t:'Cảm xúc nằm ở nhạc và bi kịch, không gắn với sản phẩm'},
             {k:'c',t:'Người xem không thích chủ đề Vu Lan'},{k:'d',t:'Logo đặt sai vị trí ở góc màn hình'}],
    answer:'b', why:{a:'Tình huống không cho thấy độ dài là vấn đề.',
      b:'Đúng. Người xem khóc vì nhạc và cảnh mẹ già, không vì điều gì liên quan đến sữa — nên nhớ cảm xúc, quên thương hiệu.',
      c:'2 triệu lượt xem cho thấy chủ đề vẫn hút.',
      d:'Vị trí logo có thể ảnh hưởng chút ít, nhưng gốc là cảm xúc không gắn với thương hiệu.'} },
  { type:'mcq', stem:'Sếp muốn làm clip Vu Lan năm sau "khóc hơn nữa". Bạn đề xuất gì?',
    options:[{k:'a',t:'Thêm tình tiết mẹ ốm nặng để cảm xúc mạnh hơn năm ngoái'},{k:'b',t:'Mời ca sĩ nổi tiếng hát nhạc phim buồn để tăng độ lan toả'},
             {k:'c',t:'Làm một clip vui nhộn để khác biệt hẳn với các thương hiệu khác mùa Vu Lan'},{k:'d',t:'Tìm một quan sát nhỏ ai cũng nhận ra, để sữa xuất hiện đúng trong khoảnh khắc đó'}],
    answer:'d', why:{a:'Bi kịch lớn hơn càng dễ bị chê "lấy nước mắt" và càng lấn át sản phẩm.',
      b:'Nhạc buồn hơn chỉ tăng kỹ xảo, không tăng sự thật.',
      c:'Khác biệt là tốt, nhưng bỏ hẳn cảm xúc thì mất đúng thứ mùa Vu Lan cần.',
      d:'Đúng. Cảm xúc từ quan sát đúng thì người xem nhận ra mình, và sản phẩm nằm trong khoảnh khắc đó.'} },
  { type:'mcq', stem:'Phép thử nhanh nào giúp phân biệt cảm xúc thật và kỹ xảo trong kịch bản?',
    options:[{k:'a',t:'Bỏ nhạc đi, xem cảnh đó còn chạm không'},{k:'b',t:'Đếm số cảnh có người khóc trong kịch bản'},
             {k:'c',t:'Hỏi đạo diễn xem có tự tin với cảnh đó không'},{k:'d',t:'Đo xem clip có nhiều lượt chia sẻ hơn clip năm trước của chính thương hiệu không'}],
    answer:'a', why:{a:'Đúng. Nếu cảm xúc sống được khi không có nhạc, nó nằm trong câu chuyện.',
      b:'Số cảnh khóc đo mức ép cảm xúc, không đo độ thật.',
      c:'Sự tự tin của đạo diễn không phải phép thử với người xem.',
      d:'Lượt chia sẻ đo được sau khi phát sóng; clip "lấy nước mắt" vẫn có thể được chia sẻ nhiều.'} },
  { type:'mcq', stem:'Chi tiết nào tạo cảm xúc thật nhất cho một quảng cáo về mẹ?',
    options:[{k:'a',t:'Mẹ nằm viện, con chạy vội trong mưa'},{k:'b',t:'Chữ "Mẹ là tất cả" hiện trên nền hoàng hôn'},
             {k:'c',t:'Mẹ hỏi "ăn cơm chưa" ba lần trong một cuộc gọi'},{k:'d',t:'Mẹ khóc khi nhận quà, nhạc violin vang lên và máy quay từ từ lùi xa'}],
    answer:'c', why:{a:'Bi kịch lớn và cảnh mưa là công thức, người xem đoán trước được.',
      b:'Khẩu hiệu đạo lý là "nói" cảm xúc, không "cho thấy" nó.',
      c:'Đúng. Hành động nhỏ, lặp lại, ai cũng nhận ra mẹ mình trong đó.',
      d:'Nhạc và máy quay làm việc ép cảm xúc; bản thân hành động khóc khi nhận quà rất chung chung.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng mì gói muốn làm clip cảm động về sinh viên xa nhà. Hướng nào tránh được "sến"?',
    options:[{k:'a',t:'Sinh viên nghèo ốm một mình trong phòng trọ, ăn mì trong nước mắt, nhớ mẹ ở quê xa'},{k:'b',t:'Sinh viên chia gói mì cuối tháng làm hai bữa, bạn cùng phòng lén bỏ thêm quả trứng'},
             {k:'c',t:'Giọng đọc nói về "tuổi trẻ gian khó nhưng đầy hoài bão"'},{k:'d',t:'Sinh viên tốt nghiệp thủ khoa, cảm ơn gói mì đã đồng hành suốt 4 năm'}],
    answer:'b', why:{a:'Nước mắt và bệnh tật là ép cảm xúc; dễ bị chê bi thảm hoá.',
      b:'Đúng. Quan sát nhỏ, có thật, ấm áp — cảm xúc đến từ hành động, không từ lời kể.',
      c:'Lời đạo lý chung chung, không có khoảnh khắc nào để nhận ra.',
      d:'Thủ khoa cảm ơn gói mì là kịch bản quá xa đời thật, khó tin.'} },
  { type:'mcq', stem:'Vì sao dùng bi kịch lớn cho sản phẩm thường ngày dễ phản tác dụng?',
    options:[{k:'a',t:'Vì đài truyền hình không cho phát cảnh bi kịch vào khung giờ vàng'},{k:'b',t:'Vì người xem Việt Nam thường không thích xem clip buồn trên mạng xã hội'},
             {k:'c',t:'Vì bi kịch tốn chi phí sản xuất hơn'},{k:'d',t:'Vì khoảng cách giữa nỗi đau lớn và món hàng nhỏ khiến khách thấy bị lợi dụng'}],
    answer:'d', why:{a:'Không có căn cứ; và lý do chính nằm ở cảm nhận của người xem.',
      b:'Clip buồn vẫn được xem nhiều; vấn đề là cảm giác bị lợi dụng.',
      c:'Chi phí không phải lý do chính.',
      d:'Đúng. Đặt một hộp sữa cạnh nỗi đau mất mát khiến người xem thấy thương hiệu đang mượn nỗi đau để bán hàng.'} },
  { type:'mcq', stem:'Clip được một nửa khen "khóc thật", một nửa chê "bán sữa bằng nước mắt". Kết luận nào hợp lý?',
    options:[{k:'a',t:'Clip thành công vì gây tranh luận, tranh luận càng nhiều càng tốt cho thương hiệu'},{k:'b',t:'Cảm xúc có tác dụng với một phần khán giả nhưng tạo nghi ngờ ở phần còn lại'},
             {k:'c',t:'Nửa chê là anti-fan, không cần quan tâm'},{k:'d',t:'Nên xoá clip ngay để tránh khủng hoảng'}],
    answer:'b', why:{a:'Tranh luận không tự thành doanh số, và chỉ 22% nhớ đúng thương hiệu.',
      b:'Đúng. Một nửa người xem thấy bị thao túng là tín hiệu cần điều chỉnh cách tạo cảm xúc.',
      c:'Một nửa khán giả không phải là nhóm nhỏ có thể bỏ qua.',
      d:'Chê bai về giọng điệu chưa phải khủng hoảng; xoá vội là phản ứng quá mức.'} },
  ]},

/* ------------------------------------------------------------------ 05 */
{ id:'B:tp09-05', skill:'creative', read:'6 phút', t:'Chi tiết nào làm câu chuyện đáng tin?',
  situation:'Một hãng giày chạy bộ nội địa đăng hai bài kể chuyện khách hàng. Bài A: "Anh Minh đã vượt qua giới hạn bản thân nhờ đôi giày đồng hành." Bài B: "Anh Minh, 38 tuổi, kế toán ở Đà Nẵng, bắt đầu chạy lúc 5 giờ sáng quanh cầu Rồng vì cân nặng 86 kg; sau 7 tháng và khoảng 1.100 km, anh về đích 21 km đầu tiên." Bài A có 320 lượt tương tác, bài B có 2.400.',
  concept:{ name:'Chi tiết cụ thể là bằng chứng ngầm',
    body:'Tính từ ("vượt qua giới hạn", "đồng hành", "tuyệt vời") thì ai cũng viết được, nên người đọc không tin. <b>Chi tiết cụ thể</b> — tên, tuổi, nghề, giờ, nơi chốn, con số, một đồ vật — là thứ khó bịa, nên chúng làm câu chuyện đáng tin. Chi tiết còn giúp người đọc <b>nhìn thấy</b> cảnh. Nguyên tắc: thay mỗi tính từ bằng một điều có thể chụp ảnh hoặc đếm được. Nhưng đừng nhồi: 3–5 chi tiết đắt giá tốt hơn 15 chi tiết vụn.' },
  example:'Bài B có tuổi (38), nghề (kế toán), nơi (cầu Rồng), giờ (5 giờ sáng), lý do (86 kg), quãng thời gian (7 tháng), quãng đường (1.100 km). Mỗi chi tiết khiến câu chuyện kiểm chứng được. Tương tác gấp 7,5 lần. Đôi giày không cần được khen: chỉ cần 1.100 km là người đọc tự suy ra "giày chịu được".',
  takeaway:'Thay mỗi tính từ bằng một điều chụp được hoặc đếm được.',
  apply:'Lấy một câu quảng cáo có tính từ "chất lượng" hoặc "tận tâm". Viết lại bằng một chi tiết cụ thể trong 60 giây.',
  mistakes:['Viết bằng tính từ cảm xúc vì nghĩ chúng "mạnh" hơn.','Nhồi quá nhiều số liệu khiến câu chuyện thành bảng thông số.'],
  q:[
  { type:'mcq', stem:'Hai bài kể cùng một khách hàng. Theo bạn, vì sao bài B tương tác gấp nhiều lần bài A?',
    options:[{k:'a',t:'Bài B dài hơn nên thuật toán mạng xã hội ưu tiên phân phối rộng hơn'},{k:'b',t:'Bài B có ảnh đẹp hơn'},
             {k:'c',t:'Chi tiết cụ thể khiến chuyện đáng tin và người đọc nhìn thấy được cảnh'},{k:'d',t:'Người đọc thích nội dung về giảm cân'}],
    answer:'c', why:{a:'Độ dài không tự tạo tương tác; nhiều bài dài vẫn bị lướt qua.',
      b:'Tình huống không nói gì về ảnh.',
      c:'Đúng. Tuổi, nơi, giờ, số km — những thứ khó bịa — làm người đọc tin và hình dung được.',
      d:'Giảm cân chỉ là một chi tiết; bài A cũng có thể viết về giảm cân mà vẫn nhạt.'} },
  { type:'mcq', stem:'Bạn phải viết lại câu "Chị Lan hài lòng với dịch vụ tận tâm của chúng tôi" cho spa. Bạn chọn bản nào?',
    options:[{k:'a',t:'"Chị Lan vô cùng hài lòng với dịch vụ tận tâm, chu đáo, chuyên nghiệp"'},{k:'b',t:'"Chị Lan, khách hàng thân thiết, đánh giá 5 sao cho dịch vụ"'},
             {k:'c',t:'"Chị Lan nói spa có không gian sang trọng và đội ngũ giàu kinh nghiệm"'},{k:'d',t:'"Chị Lan quên khăn ở ghế, hôm sau nhân viên nhắn: em giặt rồi, chị ghé lấy nhé"'}],
    answer:'d', why:{a:'Chồng thêm tính từ không làm câu đáng tin hơn.',
      b:'5 sao là con số nhưng không cho thấy cảnh nào.',
      c:'Vẫn là tính từ, chỉ đổi người nói.',
      d:'Đúng. Một hành động cụ thể cho thấy "tận tâm" mà không cần nói ra chữ đó.'} },
  { type:'calc', stem:'Bài A có 320 lượt tương tác, bài B có 2.400. Bài B gấp bao nhiêu lần bài A?',
    unit:'lần', ans:7.5, tol:0.05, wrong:[[0.13,'SAI_MAU_SO'],[2080,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Số lần = tương tác bài B ÷ tương tác bài A.','2.400 ÷ 320 = <b>7,5 lần</b>.'] },
  { type:'mcq', stem:'Vì sao chi tiết "1.100 km" hiệu quả hơn câu "đôi giày cực kỳ bền"?',
    options:[{k:'a',t:'Vì con số lớn làm người đọc choáng ngợp'},{k:'b',t:'Vì người đọc tự suy ra độ bền từ một điều đếm được'},
             {k:'c',t:'Vì câu "cực kỳ bền" vi phạm quy định quảng cáo'},{k:'d',t:'Vì người chạy bộ chỉ đọc số, không đọc chữ trong các bài đăng mạng xã hội'}],
    answer:'b', why:{a:'Không phải choáng ngợp; con số hiệu quả vì kiểm chứng được và gợi hình.',
      b:'Đúng. Để người đọc tự kết luận thì họ tin hơn là được bảo phải tin.',
      c:'Không có căn cứ trong tình huống; vấn đề là độ tin chứ không phải luật.',
      d:'Khái quát quá mức về người đọc.'} },
  { type:'mcq', stem:'Tình huống mới: một bài kể chuyện khách của hãng xe máy điện liệt kê 18 thông số kỹ thuật trong 200 chữ. Vấn đề là gì?',
    options:[{k:'a',t:'Thiếu thông số về pin và thời gian sạc'},{k:'b',t:'Nhồi chi tiết vụn, câu chuyện thành bảng thông số'},
             {k:'c',t:'Bài quá ngắn so với lượng thông số cần truyền tải'},{k:'d',t:'Nên chuyển toàn bộ thông số sang dạng video để người xem dễ theo dõi hơn'}],
    answer:'b', why:{a:'Thêm thông số càng làm nặng thêm vấn đề.',
      b:'Đúng. 3–5 chi tiết đắt giá gắn với nhân vật mạnh hơn 18 con số rời.',
      c:'Kéo dài bài không giải quyết việc thiếu nhân vật và trở ngại.',
      d:'Đổi định dạng không sửa được lỗi cấu trúc câu chuyện.'} },
  { type:'mcq', stem:'Chi tiết nào đắt giá nhất cho câu chuyện về một tiệm bánh mì gia truyền?',
    options:[{k:'a',t:'"Bánh mì ngon nổi tiếng khắp thành phố"'},{k:'b',t:'"Tiệm có menu đa dạng hơn 20 loại nhân khác nhau"'},
             {k:'c',t:'"Được nhiều người yêu thích và đánh giá cao"'},{k:'d',t:'"Lò than vẫn nhóm từ 3 giờ sáng, như từ năm 1989"'}],
    answer:'d', why:{a:'Tính từ chung chung, tiệm nào cũng nói được.',
      b:'Con số có nhưng không gợi ra điều gì về "gia truyền".',
      c:'Lời khen chung không kiểm chứng được.',
      d:'Đúng. Giờ giấc, đồ vật, năm tháng — một cảnh nhìn thấy được và khó bịa.'} },
  { type:'mcq', stem:'Nguyên tắc sửa câu nào đúng tinh thần bài này?',
    options:[{k:'a',t:'Thêm tính từ mạnh hơn để câu văn có cảm xúc'},{k:'b',t:'Dùng càng nhiều con số càng tốt, vì số liệu luôn đáng tin'},
             {k:'c',t:'Thay tính từ bằng điều chụp được hoặc đếm được'},{k:'d',t:'Giữ câu ngắn và chung chung để phù hợp nhiều người đọc khác nhau'}],
    answer:'c', why:{a:'Tính từ mạnh vẫn là lời tự khen, không phải bằng chứng.',
      b:'Quá nhiều số làm loãng; cần chọn chi tiết đắt giá.',
      c:'Đúng. Chi tiết nhìn thấy được làm câu đáng tin.',
      d:'Chung chung để hợp mọi người thường thành không chạm ai.'} },
  ]},

/* ------------------------------------------------------------------ 06 */
{ id:'B:tp09-06', skill:'channel', read:'6 phút', t:'Kể một câu chuyện trong 15 giây được không?',
  situation:'Một thương hiệu trà sữa có TVC 60 giây kể chuyện hai bạn thân giận nhau rồi làm lành bên ly trà. Kế hoạch mới chạy chủ yếu trên TikTok và YouTube Shorts, với định dạng 15 giây. Bản cắt thô đầu tiên — lấy 15 giây đẹp nhất của TVC — cho tỉ lệ xem hết 12%, trong khi các clip 15 giây khác của ngành trung bình khoảng 25%.',
  concept:{ name:'Nén chuyện: vào thẳng trở ngại, thay đổi bằng một hình',
    body:'15 giây vẫn đủ cho câu chuyện nếu bỏ phần dạo đầu. Cấu trúc nén: <b>giây 0–3</b> vào thẳng trở ngại (người xem phải hiểu ngay có chuyện gì), <b>giây 3–11</b> một hành động dẫn tới thay đổi, <b>giây 11–15</b> một hình ảnh cho thấy thay đổi cùng thương hiệu. Không cắt ngắn clip dài; hãy viết lại cho 15 giây. Cắt thô thường mất đúng phần trở ngại — thứ giữ người xem ở lại.' },
  example:'Viết lại: giây 0–3, tin nhắn "Thôi khỏi đi chung nữa" hiện trên màn hình điện thoại. Giây 3–11, một bạn đứng trước quầy, gọi hai ly, ghi lên ly kia tên bạn mình. Giây 11–15, hai ly đặt cạnh nhau, tin nhắn mới: "Ra cổng đi." Logo. Tỉ lệ xem hết bản viết lại: 27%, so với 12% của bản cắt thô.',
  takeaway:'Đừng cắt ngắn chuyện dài; viết chuyện mới bắt đầu ngay từ trở ngại.',
  apply:'Chọn một quảng cáo 60 giây bạn thích. Viết lại thành 3 khung: 0–3 giây, 3–11 giây, 11–15 giây.',
  mistakes:['Cắt 15 giây "đẹp nhất" từ TVC dài và mất luôn trở ngại.','Dành 3 giây đầu cho logo hoặc cảnh mở màn không có chuyện.'],
  q:[
  { type:'mcq', stem:'Bản cắt 15 giây từ TVC 60 giây chỉ đạt 12% xem hết. Theo bạn, vì sao?',
    options:[{k:'a',t:'Cảnh đẹp nhất thường thiếu trở ngại, người xem không có lý do ở lại'},{k:'b',t:'Người xem TikTok không quan tâm đến trà sữa'},
             {k:'c',t:'Chất lượng hình ảnh TVC quá cao so với định dạng dọc của nền tảng'},{k:'d',t:'15 giây quá ngắn cho bất kỳ câu chuyện nào'}],
    answer:'a', why:{a:'Đúng. Cắt theo "đẹp" thường lấy cảnh cao trào mà bỏ bối cảnh; người xem không biết chuyện gì đang xảy ra.',
      b:'Ngành trung bình 25% cho thấy người xem vẫn xem clip trà sữa.',
      c:'Chất lượng hình không phải lý do khiến người xem rời đi sớm.',
      d:'Bản viết lại đạt 27% cho thấy 15 giây đủ nếu được viết cho 15 giây.'} },
  { type:'mcq', stem:'Bạn có ngân sách làm lại một bản 15 giây. Bạn chọn cách nào?',
    options:[{k:'a',t:'Cắt lại TVC, chọn các cảnh khác để thử'},{k:'b',t:'Tăng tốc toàn bộ TVC 60 giây lên gấp 4 lần tốc độ'},
             {k:'c',t:'Giữ bản cắt thô, tăng ngân sách phân phối để bù tỉ lệ xem'},{k:'d',t:'Viết kịch bản mới: 3 giây đầu là trở ngại, kết là hình ảnh thay đổi'}],
    answer:'d', why:{a:'Cắt lần nữa vẫn bị ràng buộc bởi cấu trúc 60 giây.',
      b:'Tăng tốc làm mất cảm xúc và khó theo dõi.',
      c:'Tăng tiền cho clip bị bỏ giữa chừng là tăng lãng phí.',
      d:'Đúng. 15 giây cần kịch bản riêng, bắt đầu từ trở ngại.'} },
  { type:'mcq', stem:'Trong 3 giây đầu của clip 15 giây, nên đặt gì?',
    options:[{k:'a',t:'Logo thương hiệu to rõ để khách nhận diện'},{k:'b',t:'Cảnh toàn cửa hàng để giới thiệu không gian'},
             {k:'c',t:'Trở ngại mà người xem hiểu ngay lập tức'},{k:'d',t:'Lời chào của người dẫn chuyện và tên chương trình khuyến mãi đang diễn ra'}],
    answer:'c', why:{a:'Logo đầu clip là tín hiệu "quảng cáo", nhiều người lướt đi ngay.',
      b:'Cảnh toàn không có chuyện gì xảy ra, không có lý do ở lại.',
      c:'Đúng. Trở ngại tạo câu hỏi "rồi sao?" ngay từ đầu.',
      d:'Lời chào và khuyến mãi tiêu mất những giây quý nhất.'} },
  { type:'mcq', stem:'Ở phần thay đổi (giây 11–15), cách nào hiệu quả nhất?',
    options:[{k:'a',t:'Một giọng đọc giải thích bài học của câu chuyện'},{k:'b',t:'Một hình ảnh cho thấy điều đã khác, kèm thương hiệu'},
             {k:'c',t:'Liệt kê 3 ưu điểm sản phẩm trên màn hình'},{k:'d',t:'Chèn mã giảm giá kèm hướng dẫn cách dùng mã trên ứng dụng'}],
    answer:'b', why:{a:'Giải thích bằng lời tốn thời gian và làm chuyện sến.',
      b:'Đúng. Một hình như hai ly cạnh nhau truyền tải thay đổi nhanh hơn mọi câu chữ.',
      c:'Liệt kê ưu điểm biến kết chuyện thành catalogue.',
      d:'Mã giảm giá có thể thêm, nhưng không thay được hình ảnh thay đổi.'} },
  { type:'mcq', stem:'Tình huống mới: một ứng dụng giao đồ ăn cần clip 15 giây. Mở đầu nào tốt nhất?',
    options:[{k:'a',t:'Logo ứng dụng xoay tròn kèm nhạc hiệu thương hiệu'},{k:'b',t:'Người dẫn chương trình chào khán giả'},
             {k:'c',t:'Cảnh mở tủ lạnh trống lúc 11 giờ đêm, bụng réo, mai thi cuối kỳ'},{k:'d',t:'Toàn cảnh thành phố về đêm lung linh với ánh đèn xe cộ'}],
    answer:'c', why:{a:'Logo mở đầu không tạo lý do xem tiếp.',
      b:'Lời chào là dạo đầu, tốn giây quý.',
      c:'Đúng. Trở ngại rõ trong 3 giây: đói, muộn, không có gì ăn, không có thời gian.',
      d:'Cảnh đẹp nhưng không có chuyện gì.'} },
  { type:'calc', stem:'Clip 15 giây được hiển thị cho 200.000 người. Bản cắt thô có 12% xem hết, bản viết lại 27%. Bản viết lại có thêm bao nhiêu người xem hết?',
    unit:'người', ans:30000, tol:1, wrong:[[54000,'NHAM_SO_TUYET_DOI'],[15,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Bản cắt thô: 200.000 × 12% = 24.000 người.','Bản viết lại: 200.000 × 27% = 54.000 người.','Chênh lệch: 54.000 − 24.000 = <b>30.000 người</b>.'] },
  { type:'mcq', stem:'Câu nào mô tả đúng quan hệ giữa TVC 60 giây và clip 15 giây?',
    options:[{k:'a',t:'Clip 15 giây nên là bản rút gọn trung thành của TVC 60 giây'},{k:'b',t:'Clip 15 giây không cần câu chuyện, chỉ cần sản phẩm và giá'},
             {k:'c',t:'Nên bỏ TVC 60 giây vì người xem bây giờ chỉ xem clip ngắn'},{k:'d',t:'Cùng ý tưởng, nhưng clip 15 giây cần kịch bản riêng viết cho 15 giây'}],
    answer:'d', why:{a:'Rút gọn trung thành giữ cấu trúc chậm của bản dài.',
      b:'Bản viết lại cho thấy chuyện vẫn hiệu quả ở 15 giây.',
      c:'Định dạng dài vẫn có chỗ; vấn đề là mỗi định dạng cần kịch bản riêng.',
      d:'Đúng. Giữ ý tưởng, đổi cấu trúc cho độ dài.'} },
  ]},

/* ------------------------------------------------------------------ 07 */
{ id:'B:tp09-07', skill:'comm', read:'7 phút', t:'Câu chuyện khách hàng thật (UGC) dùng thế nào cho đúng?',
  situation:'Một thương hiệu nồi chiên không dầu nhận được khoảng 300 video khách tự quay mỗi tháng. Team muốn dùng lại làm quảng cáo. Hai hướng: (A) thuê biên tập dựng thành một clip "chuyên nghiệp" có nhạc, chữ động, lồng tiếng; (B) chọn 5 video gốc, chỉ thêm phụ đề và logo nhỏ ở cuối. Thử nghiệm hai tuần, cùng ngân sách: A có chi phí mỗi đơn 145.000đ, B là 92.000đ.',
  concept:{ name:'UGC mạnh nhờ nó không trông như quảng cáo',
    body:'Nội dung do khách tự làm (<b>UGC</b>) có sức nặng vì nó là bằng chứng từ người ngoài: góc quay vụng, ánh sáng bếp nhà, giọng nói thật. Khi thương hiệu "làm đẹp" quá mức, UGC mất đúng thứ làm nên giá trị của nó. Cách dùng đúng: <b>chọn</b> video có câu chuyện rõ (trở ngại + thay đổi), <b>xin phép</b> người quay rõ ràng trước khi dùng cho quảng cáo, <b>giữ nguyên</b> giọng và khung hình, chỉ thêm phụ đề cho dễ xem không cần tiếng.' },
  example:'Trong 300 video, 5 video được chọn đều có mạch chuyện: "nhà 4 người, mỗi lần chiên cá là khói cả phòng", "con không ăn rau, giờ đòi ăn đậu bắp chiên". Chủ video đồng ý cho dùng, nhận quà cảm ơn. Chi phí mỗi đơn của B thấp hơn A khoảng 37%, vì người xem không lướt qua như lướt quảng cáo.',
  takeaway:'UGC có giá trị vì nó thật; làm nó trông như quảng cáo là tự xoá giá trị đó.',
  apply:'Tìm 3 video khách tự quay về một thương hiệu. Chọn 1 video có trở ngại và thay đổi rõ nhất, nói trong 60 giây vì sao.',
  mistakes:['Dựng lại UGC cho "chuyên nghiệp" và làm mất chất thật.','Dùng video của khách làm quảng cáo mà không xin phép rõ ràng.'],
  q:[
  { type:'mcq', stem:'Hai cách dùng UGC: dựng lại chuyên nghiệp (A) hay giữ gốc thêm phụ đề (B). Theo bạn, cách nào hiệu quả hơn?',
    options:[{k:'a',t:'A, vì chất lượng sản xuất cao luôn tạo được niềm tin mạnh hơn video quay bằng điện thoại'},{k:'b',t:'Như nhau, vì nội dung giống nhau'},
             {k:'c',t:'B, vì giữ được vẻ thật, người xem không lướt qua như quảng cáo'},{k:'d',t:'A, vì có lồng tiếng nên người xem dễ hiểu hơn'}],
    answer:'c', why:{a:'Chất lượng cao làm UGC trông như quảng cáo, mất đi sức nặng của lời người ngoài.',
      b:'Nội dung giống nhưng cách trình bày thay đổi độ tin.',
      c:'Đúng. Vẻ vụng và thật là tín hiệu "đây là khách thật", thứ khiến người xem dừng lại.',
      d:'Lồng tiếng thay giọng thật là bỏ đi yếu tố đáng tin nhất.'} },
  { type:'mcq', stem:'Bạn có 300 video khách gửi mỗi tháng. Để làm quảng cáo, bạn chọn video theo tiêu chí nào?',
    options:[{k:'a',t:'Video nhiều lượt xem nhất trên trang của khách'},{k:'b',t:'Video có trở ngại và thay đổi rõ, và chủ video đồng ý cho dùng'},
             {k:'c',t:'Video có ánh sáng đẹp và góc quay chuyên nghiệp nhất'},{k:'d',t:'Video của người có nhiều người theo dõi nhất trong số khách gửi về'}],
    answer:'b', why:{a:'Lượt xem cũ phản ánh mạng lưới của người đăng, không phản ánh chuyện có hợp quảng cáo không.',
      b:'Đúng. Có mạch chuyện thì mới thuyết phục; có sự đồng ý thì mới được dùng.',
      c:'Tiêu chí "đẹp" dễ chọn trúng video giống quảng cáo nhất.',
      d:'Người nổi tiếng là KOL, không còn là tiếng nói của khách bình thường.'} },
  { type:'calc', stem:'Chi phí mỗi đơn: bản A 145.000đ, bản B 92.000đ. Bản B thấp hơn bản A bao nhiêu phần trăm? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:36.6, tol:0.1, wrong:[[57.6,'SAI_MAU_SO'],[53,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO'],
    steps:['Chênh lệch: 145.000 − 92.000 = 53.000đ.','So với mức gốc A: 53.000 ÷ 145.000 ≈ 0,3655 = <b>36,6%</b>.'] },
  { type:'mcq', stem:'Nên chỉnh sửa UGC ở mức nào khi dùng làm quảng cáo?',
    options:[{k:'a',t:'Thêm phụ đề và logo nhỏ, giữ giọng và khung hình gốc'},{k:'b',t:'Chỉnh màu, thêm nhạc, lồng lại tiếng cho chuẩn'},
             {k:'c',t:'Quay lại toàn bộ với diễn viên theo đúng kịch bản của khách'},{k:'d',t:'Không được sửa gì kể cả phụ đề, vì bất kỳ chỉnh sửa nào cũng làm mất tính thật'}],
    answer:'a', why:{a:'Đúng. Phụ đề giúp xem không tiếng; logo nhỏ giúp nhớ thương hiệu; còn lại giữ nguyên.',
      b:'Mỗi lớp chỉnh sửa lại làm video xa dần khỏi vẻ thật.',
      c:'Diễn viên đóng lại thì không còn là UGC.',
      d:'Phụ đề không làm mất vẻ thật; nhiều người xem không bật tiếng.'} },
  { type:'mcq', stem:'Tình huống mới: một khách đăng video khen sản phẩm, team tải về và chạy quảng cáo ngay vì "video công khai". Vấn đề là gì?',
    options:[{k:'a',t:'Video chưa được chỉnh màu cho chuyên nghiệp'},{k:'b',t:'Video quá ngắn để chạy quảng cáo'},
             {k:'c',t:'Nên chờ video đạt đủ lượt xem rồi mới dùng làm quảng cáo cho thương hiệu'},{k:'d',t:'Dùng video của khách cho quảng cáo mà chưa xin phép rõ ràng'}],
    answer:'d', why:{a:'Chỉnh màu không phải vấn đề, thậm chí còn làm mất chất thật.',
      b:'Tình huống không cho thấy độ dài là vấn đề.',
      c:'Lượt xem không thay thế được sự đồng ý của chủ video.',
      d:'Đúng. Công khai không đồng nghĩa với cho phép dùng làm quảng cáo; phải xin phép rõ ràng.'} },
  { type:'mcq', stem:'Video UGC nào có giá trị câu chuyện cao nhất cho nồi chiên không dầu?',
    options:[{k:'a',t:'Mở hộp, quay từng phụ kiện, khen "đẹp quá"'},{k:'b',t:'"Chiên cá là khói cả phòng, giờ nhà 4 người ăn cá mỗi tuần"'},
             {k:'c',t:'Đọc lại thông số công suất và dung tích trên vỏ hộp'},{k:'d',t:'Quay cảnh nồi chạy 20 phút liên tục từ một góc không đổi'}],
    answer:'b', why:{a:'Mở hộp có ích cho người đang cân nhắc mẫu, nhưng không có trở ngại và thay đổi.',
      b:'Đúng. Có trở ngại thật (khói) và thay đổi cụ thể (ăn cá mỗi tuần).',
      c:'Đọc thông số là việc thương hiệu đã làm; không có câu chuyện.',
      d:'Không có nhân vật, không có trở ngại.'} },
  { type:'mcq', stem:'Vì sao UGC thường thuyết phục hơn quảng cáo do thương hiệu tự làm?',
    options:[{k:'a',t:'Vì nó rẻ hơn nên thương hiệu chạy được nhiều hơn'},{k:'b',t:'Vì thuật toán luôn ưu tiên video quay bằng điện thoại'},
             {k:'c',t:'Vì nó là bằng chứng từ người ngoài, không phải lời tự khen'},{k:'d',t:'Vì người xem thích sự vụng về và đánh giá thấp mọi nội dung được sản xuất chỉn chu'}],
    answer:'c', why:{a:'Rẻ là lợi ích chi phí, không giải thích sức thuyết phục.',
      b:'Không có căn cứ rằng thuật toán luôn ưu tiên như vậy.',
      c:'Đúng. Người xem tin người giống mình hơn tin thương hiệu tự nói về mình.',
      d:'Người xem không ghét chỉn chu; họ tin lời người ngoài hơn lời tự khen.'} },
  ]},

/* ------------------------------------------------------------------ 08 */
{ id:'B:tp09-08', skill:'creative', read:'7 phút', t:'Quảng cáo Tết kể chuyện gia đình mà không sáo, làm sao?',
  situation:'Tháng 11, một hãng bánh kẹo họp brief quảng cáo Tết. Ba ý tưởng đầu tiên team đưa ra: con xa quê về nhà ăn Tết, cả nhà quây quần gói bánh chưng, bố mẹ già chờ con ở cổng. Một bạn trong team nhận xét: "Năm ngoái em xem lại 20 quảng cáo Tết, 7 cái có đúng cảnh bố mẹ chờ ở cổng."',
  concept:{ name:'Tìm sự thật mới bên trong chủ đề cũ',
    body:'Tết đoàn viên là chủ đề không đổi — và không cần đổi. Cái sáo không nằm ở chủ đề mà ở <b>khoảnh khắc</b> được chọn: ai cũng quay cảnh chờ ở cổng, cảnh gói bánh chưng. Cách thoát: tìm một <b>sự thật nhỏ, mới, có thật</b> của Tết hôm nay mà chưa ai quay — những căng thẳng, thói quen, mâu thuẫn dễ thương mà người xem nhận ra ngay. Kiểm tra: nếu thay logo bằng logo đối thủ mà quảng cáo vẫn đúng, ý tưởng chưa đủ riêng.' },
  example:'Team đổi hướng, liệt kê những khoảnh khắc Tết có thật nhưng ít được quay: bị họ hàng hỏi "bao giờ lấy vợ"; bố lén giữ hộp bánh ngon nhất cho con út; mẹ bày khay mứt từ 28 Tết, cấm ai đụng vào. Chọn cảnh cuối: cả nhà lén ăn vụng khay mứt, mẹ phát hiện, rồi mẹ cũng ngồi xuống ăn cùng. Hộp bánh kẹo chính là khay mứt đó — thương hiệu gắn vào đúng khoảnh khắc.',
  takeaway:'Giữ chủ đề Tết, đổi khoảnh khắc: tìm một sự thật nhỏ chưa ai quay.',
  apply:'Liệt kê 5 khoảnh khắc Tết của nhà bạn chưa từng thấy trong quảng cáo. Chọn 1 và nói vì sao nó gắn được với một sản phẩm.',
  mistakes:['Bỏ hẳn chủ đề gia đình để "khác biệt" và mất sự liên quan với mùa Tết.','Chọn khoảnh khắc ai cũng quay, thay logo đối thủ vào vẫn đúng.'],
  q:[
  { type:'mcq', stem:'Ba ý tưởng: con về quê, gói bánh chưng, bố mẹ chờ ở cổng. Theo bạn, vấn đề lớn nhất là gì?',
    options:[{k:'a',t:'Chủ đề gia đình đã lỗi thời, nên đổi sang chủ đề du lịch Tết cho mới mẻ hơn'},{k:'b',t:'Chi phí quay cảnh quê tốn kém'},
             {k:'c',t:'Khoảnh khắc đã được quay quá nhiều, thay logo nào vào cũng đúng'},{k:'d',t:'Người trẻ không còn về quê ăn Tết'}],
    answer:'c', why:{a:'Chủ đề gia đình vẫn đúng với Tết; vấn đề là khoảnh khắc được chọn.',
      b:'Chi phí không phải vấn đề chiến lược.',
      c:'Đúng. Khi khoảnh khắc là của chung cả ngành, thương hiệu không được nhớ riêng.',
      d:'Khái quát sai; phần đông vẫn về nhà ăn Tết.'} },
  { type:'mcq', stem:'Bạn dẫn buổi brainstorm tiếp theo. Bạn yêu cầu team làm gì?',
    options:[{k:'a',t:'Liệt kê khoảnh khắc Tết có thật nhưng ít được quay, rồi chọn cái gắn với sản phẩm'},{k:'b',t:'Bỏ Tết, làm một quảng cáo không liên quan mùa lễ để nổi bật'},
             {k:'c',t:'Giữ cảnh chờ ở cổng nhưng mời diễn viên nổi tiếng hơn đối thủ'},{k:'d',t:'Xem lại 20 quảng cáo Tết năm ngoái và làm theo cái có lượt xem cao nhất'}],
    answer:'a', why:{a:'Đúng. Giữ chủ đề, đổi khoảnh khắc — nguồn của sự riêng biệt.',
      b:'Bỏ Tết mùa Tết là tự tách khỏi lý do khách mua bánh kẹo lúc này.',
      c:'Diễn viên nổi tiếng không làm khoảnh khắc sáo thành mới.',
      d:'Làm theo cái đã có là cách chắc chắn nhất để trở nên sáo.'} },
  { type:'mcq', stem:'Phép thử nhanh nào cho biết ý tưởng Tết đã đủ riêng chưa?',
    options:[{k:'a',t:'Đếm số lần xuất hiện cảnh bánh chưng và câu đối trong kịch bản'},{k:'b',t:'Hỏi xem ý tưởng có làm người xem rơi nước mắt không'},
             {k:'c',t:'Kiểm tra xem kịch bản có đủ các biểu tượng Tết như hoa mai, hoa đào, câu đối đỏ'},{k:'d',t:'Thay logo đối thủ vào, xem quảng cáo có còn đúng không'}],
    answer:'d', why:{a:'Đếm biểu tượng không cho biết ý tưởng có riêng không.',
      b:'Rơi nước mắt không đồng nghĩa với riêng biệt.',
      c:'Biểu tượng Tết là của chung, càng nhiều càng giống người khác.',
      d:'Đúng. Nếu logo nào cũng hợp, câu chuyện không thuộc về ai cả.'} },
  { type:'mcq', stem:'Vì sao chọn cảnh "cả nhà lén ăn vụng khay mứt của mẹ" gắn tốt với hãng bánh kẹo?',
    options:[{k:'a',t:'Vì cảnh vui nhộn luôn hiệu quả hơn cảnh cảm động trong mùa Tết'},{k:'b',t:'Vì sản phẩm nằm đúng giữa khoảnh khắc, không phải gắn thêm vào'},
             {k:'c',t:'Vì cảnh này rẻ, quay trong một căn phòng'},{k:'d',t:'Vì mẹ là nhân vật được yêu thích nhất'}],
    answer:'b', why:{a:'Không có quy luật vui luôn thắng; điều quan trọng là sản phẩm gắn với khoảnh khắc.',
      b:'Đúng. Hộp bánh kẹo chính là khay mứt — không có sản phẩm thì không có chuyện.',
      c:'Chi phí thấp là lợi ích phụ, không giải thích độ gắn kết.',
      d:'Nhân vật mẹ có thể được yêu thích, nhưng lý do chính là vai trò của sản phẩm.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng ví điện tử làm quảng cáo Tết. Khoảnh khắc nào vừa mới vừa gắn với sản phẩm?',
    options:[{k:'a',t:'Cả nhà quây quần đêm giao thừa xem pháo hoa'},{k:'b',t:'Con đi làm xa gửi quà về cho bố mẹ kèm lời chúc, bố mẹ xúc động mở quà trước bàn thờ'},
             {k:'c',t:'Ông bà lần đầu nhận lì xì qua điện thoại, loay hoay rồi cười khi thấy tiền về'},{k:'d',t:'Hình ảnh hoa đào, hoa mai và chữ "Chúc mừng năm mới"'}],
    answer:'c', why:{a:'Cảnh giao thừa là của chung, không gắn với ví điện tử.',
      b:'Gửi quà là chủ đề quen, sản phẩm chỉ gắn lỏng lẻo.',
      c:'Đúng. Khoảnh khắc mới, có thật, và sản phẩm là trung tâm của sự thay đổi.',
      d:'Biểu tượng Tết chung, không có câu chuyện.'} },
  { type:'mcq', stem:'Một thành viên đề xuất: "Để khác biệt, làm quảng cáo Tết về người độc thân đi du lịch một mình." Nhận xét hợp lý nhất?',
    options:[{k:'a',t:'Có thể hay nếu sản phẩm liên quan, nhưng với bánh kẹo thì dễ tách khỏi lý do mua'},{k:'b',t:'Hoàn toàn sai, quảng cáo Tết bắt buộc phải về gia đình'},
             {k:'c',t:'Luôn đúng, vì khác biệt là mục tiêu quan trọng nhất của quảng cáo'},{k:'d',t:'Nên làm vì người trẻ ngày nay hầu như đều đi du lịch thay vì về quê trong dịp Tết'}],
    answer:'a', why:{a:'Đúng. Khác biệt phải phục vụ lý do mua; bánh kẹo Tết mua để bày và biếu trong gia đình.',
      b:'Không có quy tắc bắt buộc; vấn đề là độ liên quan với sản phẩm.',
      c:'Khác biệt mà không liên quan thì người xem nhớ chuyện, quên lý do mua.',
      d:'Khái quát quá mức, không có căn cứ.'} },
  { type:'calc', stem:'Bạn xem lại 20 quảng cáo Tết năm ngoái, đếm được 7 quảng cáo có cảnh bố mẹ chờ con ở cổng. Tỉ lệ quảng cáo dùng cảnh này là bao nhiêu phần trăm?',
    unit:'%', ans:35, tol:0.1, wrong:[[285.7,'SAI_MAU_SO'],[7,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ = số quảng cáo có cảnh ÷ tổng số quảng cáo xem.','7 ÷ 20 = 0,35 = <b>35%</b>.'] },
  ]},

/* ------------------------------------------------------------------ 09 */
{ id:'B:tp09-09', skill:'brand', read:'6 phút', t:'Câu chuyện hay nhưng không ai nhớ sản phẩm: sửa ở đâu?',
  situation:'Một thương hiệu dầu gội làm phim ngắn 3 phút về cô gái trẻ đi phỏng vấn xin việc lần thứ năm, cuối cùng đậu. Phim được khen nhiều, 1,5 triệu lượt xem. Nhưng khảo sát 500 người đã xem: 410 người kể lại được cốt truyện, chỉ 95 người nhớ đó là quảng cáo dầu gội, và chỉ 40 người nêu đúng tên thương hiệu.',
  concept:{ name:'Thương hiệu phải là mắt xích của câu chuyện',
    body:'Một câu chuyện có thể hay mà vẫn là quảng cáo tồi nếu <b>thương hiệu không nằm trong mạch chuyện</b>. Phép thử: rút sản phẩm ra khỏi câu chuyện — chuyện có đổi gì không? Nếu không, sản phẩm chỉ đang được "dán" vào. Cách sửa: gắn sản phẩm vào <b>điểm ngoặt</b>, nơi trở ngại chuyển thành thay đổi; và để các dấu hiệu nhận diện (màu, âm thanh, câu cửa miệng) xuất hiện sớm, lặp lại, không đợi đến giây cuối.' },
  example:'Bản gốc: dầu gội chỉ xuất hiện 2 giây cuối cùng logo. Bản sửa: đêm trước lần phỏng vấn thứ năm, cô gái nhìn gương thấy tóc bết sau ca làm thêm, định bỏ cuộc; gội đầu, tóc vào nếp, cô tự nói "thêm một lần nữa". Màu chai dầu gội xuất hiện ở gương từ phút đầu. Khảo sát lại sau khi chạy bản sửa: 180/500 người nêu đúng tên thương hiệu.',
  takeaway:'Rút sản phẩm ra mà chuyện không đổi, thì câu chuyện đó không phải của bạn.',
  apply:'Chọn một phim quảng cáo bạn nhớ cốt truyện. Nói trong 60 giây: sản phẩm có nằm ở điểm ngoặt không, hay chỉ ở cuối.',
  mistakes:['Để logo chỉ xuất hiện ở giây cuối với hy vọng tạo bất ngờ.','Đo thành công bằng lượt xem và lời khen, quên đo mức nhớ thương hiệu.'],
  q:[
  { type:'mcq', stem:'410/500 người nhớ cốt truyện nhưng chỉ 40 người nhớ thương hiệu. Bạn đoán lý do chính là gì?',
    options:[{k:'a',t:'Phim quá dài nên người xem quên thương hiệu'},{k:'b',t:'Thương hiệu dầu gội quá mới, chưa ai biết'},
             {k:'c',t:'Người xem cố tình lờ đi thương hiệu vì ghét quảng cáo, dù vẫn xem hết phim'},{k:'d',t:'Sản phẩm không nằm trong mạch chuyện, chỉ được dán vào cuối'}],
    answer:'d', why:{a:'Người xem vẫn nhớ cốt truyện 3 phút, nên độ dài không phải lý do.',
      b:'Thương hiệu mới có thể khó nhớ hơn, nhưng không giải thích việc họ không nhận ra đó là quảng cáo dầu gội.',
      c:'Không có dữ kiện cho thấy người xem cố tình lờ đi.',
      d:'Đúng. Rút dầu gội ra, chuyện vẫn nguyên vẹn — đó là dấu hiệu sản phẩm chưa vào mạch chuyện.'} },
  { type:'mcq', stem:'Bạn được làm lại phim với cùng cốt truyện. Bạn sửa điểm nào đầu tiên?',
    options:[{k:'a',t:'Thêm cảnh cận chai dầu gội ở đầu và cuối phim'},{k:'b',t:'Đặt sản phẩm vào điểm ngoặt, nơi nhân vật vượt qua trở ngại'},
             {k:'c',t:'Đổi thành phim 60 giây để người xem nhớ thương hiệu hơn'},{k:'d',t:'Chèn tên thương hiệu vào lời thoại của nhân vật nhiều lần xuyên suốt câu chuyện'}],
    answer:'b', why:{a:'Thêm cảnh cận vẫn là "dán" sản phẩm, không làm nó thành mắt xích.',
      b:'Đúng. Sản phẩm ở điểm ngoặt thì nhớ chuyện là nhớ sản phẩm.',
      c:'Rút ngắn không giải quyết việc sản phẩm nằm ngoài mạch chuyện.',
      d:'Chèn tên nhiều lần làm lời thoại giả tạo và dễ bị chê.'} },
  { type:'calc', stem:'Khảo sát 500 người. Trước khi sửa, 40 người nêu đúng tên thương hiệu; sau khi sửa, 180 người. Tỉ lệ nhớ đúng thương hiệu tăng thêm bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:28, tol:0.1, wrong:[[350,'NHAM_DIEM_PHAN_TRAM'],[140,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM','NHAM_SO_TUYET_DOI'],
    steps:['Trước: 40 ÷ 500 = 8%.','Sau: 180 ÷ 500 = 36%.','Tăng: 36% − 8% = <b>28 điểm phần trăm</b>.'] },
  { type:'mcq', stem:'Phép thử nào cho biết sản phẩm đã là mắt xích của câu chuyện?',
    options:[{k:'a',t:'Rút sản phẩm ra, xem câu chuyện có còn đứng được không'},{k:'b',t:'Đếm số giây sản phẩm xuất hiện trên màn hình'},
             {k:'c',t:'Hỏi team sáng tạo xem họ có thích câu chuyện không'},{k:'d',t:'Xem logo có đủ to và đặt ở góc dễ thấy trong suốt phim không'}],
    answer:'a', why:{a:'Đúng. Nếu rút ra mà chuyện gãy, sản phẩm đang gánh một phần câu chuyện.',
      b:'Nhiều giây mà vẫn chỉ là cảnh trưng bày thì không vào mạch chuyện.',
      c:'Team thích không nói gì về việc người xem nhớ thương hiệu.',
      d:'Logo to giúp nhận diện, nhưng không làm sản phẩm thành phần của chuyện.'} },
  { type:'mcq', stem:'Vì sao để logo chỉ xuất hiện ở giây cuối "cho bất ngờ" thường có hại?',
    options:[{k:'a',t:'Vì đài truyền hình tính phí cao hơn cho giây cuối của một đoạn quảng cáo'},{k:'b',t:'Vì logo cuối phim làm hình ảnh kém đẹp'},
             {k:'c',t:'Vì nhiều người đã rời đi trước giây cuối, và trí nhớ không kịp gắn chuyện với tên'},{k:'d',t:'Vì người xem không thích bị bất ngờ'}],
    answer:'c', why:{a:'Không có căn cứ về cách tính phí như vậy.',
      b:'Thẩm mỹ không phải vấn đề chính.',
      c:'Đúng. Dấu hiệu nhận diện cần xuất hiện sớm và lặp lại để gắn vào ký ức về câu chuyện.',
      d:'Người xem thích bất ngờ trong chuyện; vấn đề là thương hiệu không kịp được ghi nhớ.'} },
  { type:'mcq', stem:'Tình huống mới: phim ngắn của hãng xe máy kể chuyện hai ông cháu, xe chỉ xuất hiện đậu ở góc sân. Sửa thế nào?',
    options:[{k:'a',t:'Thêm cảnh ông cháu khen xe đẹp và bền, nói tên dòng xe hai lần'},{k:'b',t:'Để chiếc xe là thứ đưa ông cháu đến điểm ngoặt của chuyện'},
             {k:'c',t:'Đổi màu xe sang màu nổi bật hơn để dễ thấy ở góc sân'},{k:'d',t:'Kết phim bằng thông số động cơ'}],
    answer:'b', why:{a:'Khen xe trong lời thoại làm phim giả tạo, vẫn chưa gắn vào mạch chuyện.',
      b:'Đúng. Ví dụ: ông chở cháu đi thi đúng giờ trên chiếc xe cũ — xe là mắt xích của thay đổi.',
      c:'Nổi bật hơn vẫn là đứng ngoài chuyện.',
      d:'Thông số không làm xe thành phần của câu chuyện.'} },
  { type:'mcq', stem:'Chỉ số nào quan trọng nhất để đánh giá phim ngắn này có thành công về thương hiệu?',
    options:[{k:'a',t:'Số lượt xem trên các nền tảng'},{k:'b',t:'Số lời khen trong phần bình luận dưới video'},
             {k:'c',t:'Tỉ lệ người xem nêu đúng tên thương hiệu khi kể lại'},{k:'d',t:'Số lượt chia sẻ trong tuần đầu tiên, vì chia sẻ cho thấy người xem thật sự yêu thích câu chuyện'}],
    answer:'c', why:{a:'1,5 triệu lượt xem vẫn có thể chỉ 8% nhớ đúng thương hiệu.',
      b:'Lời khen dành cho câu chuyện, không chắc dành cho thương hiệu.',
      c:'Đúng. Đó là con số cho biết câu chuyện có làm việc cho thương hiệu hay không.',
      d:'Chia sẻ cho thấy yêu thích câu chuyện, không cho thấy nhớ thương hiệu.'} },
  ]},

/* ------------------------------------------------------------------ 10 */
{ id:'B:tp09-10', skill:'measure', read:'7 phút', t:'Làm sao biết câu chuyện thương hiệu đang hiệu quả?',
  situation:'Một chuỗi cà phê chạy series 6 tập "Người ngồi bàn góc" kể chuyện khách quen. Báo cáo của agency: 3,2 triệu lượt xem, 45.000 bình luận, "cảm xúc tích cực 92%". Giám đốc hỏi: "Vậy khách có đến quán nhiều hơn không?" Không ai trả lời được. Ngân sách series tiếp theo là 600 triệu và cần được duyệt trong tháng.',
  concept:{ name:'Đo câu chuyện theo ba tầng',
    body:'Lượt xem và bình luận chỉ cho biết câu chuyện được <b>chú ý</b>. Để biết nó có hiệu quả, đo thêm hai tầng. Tầng <b>ghi nhớ</b>: người xem có nhớ đúng thương hiệu, có kể lại được thông điệp không (khảo sát nhớ lại). Tầng <b>hành vi</b>: có thay đổi gì ở tìm kiếm tên thương hiệu, lượt ghé quán, đơn hàng — tốt nhất là so khu vực/nhóm có xem với nhóm không xem. Đặt mục tiêu cho cả ba tầng <b>trước</b> khi phát sóng, không phải sau.' },
  example:'Series mới được đặt mục tiêu trước: chú ý (tỉ lệ xem hết tập ≥ 35%), ghi nhớ (≥ 30% người xem nêu đúng tên chuỗi), hành vi (lượt ghé quán tăng ở 10 quán có chạy quảng cáo địa phương, so với 10 quán tương tự không chạy). Sau 8 tuần: nhóm có chạy tăng từ trung bình 400 lên 460 lượt/ngày, nhóm đối chứng từ 400 lên 412. Phần tăng thêm quy cho series là 48 lượt/ngày mỗi quán.',
  takeaway:'Đo câu chuyện ở ba tầng: được chú ý, được nhớ đúng tên, và làm khách hành động khác đi.',
  apply:'Chọn một chiến dịch kể chuyện gần đây. Nói trong 60 giây mỗi tầng bạn sẽ đo bằng chỉ số nào.',
  mistakes:['Báo cáo lượt xem và cảm xúc tích cực như bằng chứng hiệu quả.','Không có nhóm đối chứng nên không tách được tác động của câu chuyện khỏi mùa vụ.'],
  q:[
  { type:'mcq', stem:'Báo cáo có 3,2 triệu lượt xem và 92% cảm xúc tích cực. Theo bạn, điều gì còn thiếu nhất?',
    options:[{k:'a',t:'Số lượt chia sẻ và lượt lưu video của từng tập'},{k:'b',t:'Chỉ số về việc người xem nhớ thương hiệu và có đến quán nhiều hơn không'},
             {k:'c',t:'So sánh lượt xem với series cùng thời điểm của các chuỗi cà phê đối thủ lớn trong ngành'},{k:'d',t:'Danh sách những bình luận tiêu cực'}],
    answer:'b', why:{a:'Chia sẻ và lưu vẫn là chỉ số chú ý, cùng tầng với lượt xem.',
      b:'Đúng. Thiếu tầng ghi nhớ và hành vi — hai tầng trả lời câu hỏi của giám đốc.',
      c:'So với đối thủ vẫn chỉ ở tầng chú ý.',
      d:'Bình luận tiêu cực là chi tiết, không trả lời câu hỏi hiệu quả kinh doanh.'} },
  { type:'mcq', stem:'Bạn cần xin duyệt 600 triệu cho series tiếp theo. Bạn chọn kế hoạch đo lường nào?',
    options:[{k:'a',t:'Cam kết đạt 5 triệu lượt xem, cao hơn series trước'},{k:'b',t:'Chạy series trên toàn quốc rồi so doanh thu tháng này với tháng trước'},
             {k:'c',t:'Đo tỉ lệ cảm xúc tích cực trong bình luận bằng công cụ lắng nghe mạng xã hội'},{k:'d',t:'Đặt trước mục tiêu cho ba tầng, có nhóm quán đối chứng để đo lượt ghé'}],
    answer:'d', why:{a:'Lượt xem cao hơn không trả lời câu hỏi "khách có đến nhiều hơn không".',
      b:'So tháng này với tháng trước lẫn mùa vụ, thời tiết, khuyến mãi.',
      c:'Cảm xúc tích cực vẫn chỉ ở tầng chú ý.',
      d:'Đúng. Mục tiêu đặt trước và nhóm đối chứng cho phép tách tác động của câu chuyện.'} },
  { type:'calc', stem:'Nhóm quán có chạy series: từ 400 lên 460 lượt/ngày. Nhóm đối chứng: từ 400 lên 412. Phần tăng thêm quy cho series là bao nhiêu lượt/ngày mỗi quán?',
    unit:'lượt/ngày', ans:48, tol:0.5, wrong:[[60,'QUEN_TRU_CHI_PHI_QC'],[12,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Nhóm chạy tăng: 460 − 400 = 60.','Nhóm đối chứng tăng: 412 − 400 = 12 (phần tăng tự nhiên).','Phần do series: 60 − 12 = <b>48 lượt/ngày</b>.'] },
  { type:'mcq', stem:'Vì sao cần nhóm quán đối chứng?',
    options:[{k:'a',t:'Để tách tác động của series khỏi mùa vụ và các yếu tố khác'},{k:'b',t:'Để tiết kiệm ngân sách bằng cách chỉ chạy một nửa số quán'},
             {k:'c',t:'Để có thêm quán cho nhân viên thử menu mới'},{k:'d',t:'Để báo cáo có nhiều con số hơn, trông thuyết phục hơn khi trình bày trước ban giám đốc'}],
    answer:'a', why:{a:'Đúng. Nhóm đối chứng cho biết lượt ghé sẽ tăng bao nhiêu nếu không có series.',
      b:'Tiết kiệm có thể là hệ quả, không phải mục đích.',
      c:'Không liên quan đến việc đo hiệu quả câu chuyện.',
      d:'Nhiều số hơn không phải mục đích; mục đích là tách nhân quả.'} },
  { type:'mcq', stem:'Tầng "ghi nhớ" nên đo bằng cách nào?',
    options:[{k:'a',t:'Đếm số người theo dõi trang tăng thêm'},{k:'b',t:'Tính thời gian xem trung bình của mỗi tập trong series'},
             {k:'c',t:'Khảo sát người đã xem xem họ có nêu đúng tên thương hiệu và thông điệp không'},{k:'d',t:'Đếm số lần tên thương hiệu được nhắc trong bình luận dưới các video của series'}],
    answer:'c', why:{a:'Theo dõi trang là hành vi trên mạng, không chắc phản ánh ghi nhớ.',
      b:'Thời gian xem thuộc tầng chú ý.',
      c:'Đúng. Hỏi trực tiếp người đã xem là cách đo ghi nhớ đúng thương hiệu.',
      d:'Bình luận chỉ đại diện cho nhóm nhỏ người hay bình luận.'} },
  { type:'mcq', stem:'Tình huống mới: sau series, lượt tìm kiếm tên chuỗi tăng 40% nhưng lượt ghé quán không đổi. Bạn đọc thế nào?',
    options:[{k:'a',t:'Câu chuyện đã thất bại hoàn toàn vì lượt ghé quán không tăng'},{k:'b',t:'Series thành công vì tìm kiếm là chỉ số quan trọng nhất trong mọi trường hợp'},
             {k:'c',t:'Số liệu tìm kiếm chắc chắn sai'},{k:'d',t:'Câu chuyện tạo quan tâm, nhưng có rào cản giữa quan tâm và ghé quán cần tìm'}],
    answer:'d', why:{a:'Tìm kiếm tăng là tín hiệu ghi nhớ thật; kết luận thất bại là bỏ qua dữ kiện.',
      b:'Tìm kiếm là một tầng; mục tiêu cuối vẫn là hành vi mua.',
      c:'Không có lý do để nghi số liệu khi chưa kiểm tra.',
      d:'Đúng. Có thể do vị trí quán, giờ mở cửa, giá — rào cản nằm sau câu chuyện.'} },
  { type:'mcq', stem:'Khi nào nên đặt mục tiêu đo lường cho một chiến dịch kể chuyện?',
    options:[{k:'a',t:'Sau khi phát sóng, khi đã biết chỉ số nào đẹp nhất để báo cáo'},{k:'b',t:'Trước khi phát sóng, cho cả ba tầng chú ý, ghi nhớ, hành vi'},
             {k:'c',t:'Chỉ khi ban giám đốc yêu cầu'},{k:'d',t:'Sau tập đầu tiên, khi đã có số liệu ban đầu để làm mốc so sánh cho các tập sau'}],
    answer:'b', why:{a:'Chọn chỉ số sau khi có số là tự chọn cái đẹp, không phải đo hiệu quả.',
      b:'Đúng. Mục tiêu đặt trước mới cho phép đánh giá công bằng và dựng nhóm đối chứng kịp.',
      c:'Đợi được yêu cầu thường là quá muộn để dựng đối chứng.',
      d:'Sau tập đầu thì không kịp chọn nhóm quán đối chứng từ trước.'} },
  ]},

]});
